) -> (String, String) {
    let user_id = create_user(pool, email).await;
    sqlx::query(
        "INSERT INTO calendar_acl (calendar_id, user_id, role, created_at, updated_at)
         VALUES (?, ?, ?, 100, 100)",
    )
    .bind(calendar_id)
    .bind(user_id)
    .bind(role)
    .execute(pool)
    .await
    .unwrap();
    let password = accounts
        .issue_credential(user_id, "Phone".into())
